import type { LayoutWarning } from '../agent/types.ts'
import type { ResolvedRenderRequest } from '../render-contract.ts'
import { toHex, wcagCssContrastRatio, tryParseCssColor } from '../shared/color-math.ts'
import { diagramColorVariables, MIX, resolveColors } from '../theme.ts'
import { compareCodePointStrings } from '../shared/deterministic-order.ts'
import { STYLE_OWNED_PAINT_VARIABLES, type BrandConstraint } from './style-spec.ts'
import { BRAND_CONSTRAINT_DESCRIPTORS, BRAND_CONSTRAINT_WARNING_POLICY } from './brand-constraint-contract.ts'
import { geometryBounds } from './bounds.ts'
import type { SceneDoc, SceneNode } from './ir.ts'
import { visitSceneNodes } from './walk.ts'

type BrandWarning = Extract<LayoutWarning, { code: 'BRAND_CONSTRAINT_WARNING' | 'BRAND_CONSTRAINT_ERROR' }>

function mixOpaqueCss(foreground: string, background: string, percent: number): string | undefined {
  const fg = tryParseCssColor(foreground)
  const bg = tryParseCssColor(background)
  if (!fg || !bg || fg[3] !== 1 || bg[3] !== 1) return undefined
  const ratio = percent / 100
  return toHex(
    fg[0] * ratio + bg[0] * (1 - ratio),
    fg[1] * ratio + bg[1] * (1 - ratio),
    fg[2] * ratio + bg[2] * (1 - ratio),
  )
}

function resolvedPaint(value: string | undefined, request: ResolvedRenderRequest): string | undefined {
  if (!value) return undefined
  const colors = request.appearance.colors
  const mixed = (percent: number): string | undefined => mixOpaqueCss(colors.fg, colors.bg, percent)
  // Measure the same concrete palettes and repaired tones that SVG inlines,
  // including opaque named/RGB literals, rather than their unrepaired mixes.
  const inlined = diagramColorVariables(colors) ? resolveColors(colors) : undefined
  const derived = inlined ? {
    text: inlined.text,
    textSec: inlined.textSec,
    textMuted: inlined.textMuted,
    textFaint: inlined.textFaint,
    line: inlined.line,
    arrow: inlined.arrow,
    nodeFill: inlined.nodeFill,
    nodeStroke: inlined.nodeStroke,
    groupHdr: inlined.groupHdr,
    innerStroke: inlined.innerStroke,
    keyBadge: inlined.keyBadge,
  } : {
    text: colors.fg,
    textSec: colors.muted ?? mixed(MIX.textSec),
    textMuted: colors.muted ?? mixed(MIX.textMuted),
    textFaint: mixed(MIX.textFaint),
    line: colors.line ?? mixed(MIX.line),
    arrow: colors.accent ?? mixed(MIX.arrow),
    nodeFill: colors.surface ?? mixed(MIX.nodeFill),
    nodeStroke: colors.border ?? mixed(MIX.nodeStroke),
    groupHdr: mixed(MIX.groupHeader),
    innerStroke: mixed(MIX.innerStroke),
    keyBadge: mixed(MIX.keyBadge),
  }
  const styleOwnedToken = {
    '--bg': colors.bg,
    '--fg': colors.fg,
    '--_text': derived.text,
    '--_text-sec': derived.textSec,
    '--_text-muted': derived.textMuted,
    '--_text-faint': derived.textFaint,
    '--_line': derived.line,
    '--_arrow': derived.arrow,
    '--_node-fill': derived.nodeFill,
    '--_node-stroke': derived.nodeStroke,
    '--_group-fill': colors.bg,
    '--_group-hdr': derived.groupHdr,
    '--_inner-stroke': derived.innerStroke,
    '--_key-badge': derived.keyBadge,
  } satisfies Record<(typeof STYLE_OWNED_PAINT_VARIABLES)[number], string | undefined>
  const token: Readonly<Record<string, string | undefined>> = {
    '--line': colors.line,
    '--accent': colors.accent,
    '--muted': colors.muted,
    '--surface': colors.surface,
    '--border': colors.border,
    ...styleOwnedToken,
  }
  const variable = value.match(/^var\(\s*(--[a-z0-9_-]+)(?:\s*,[\s\S]*)?\)$/i)?.[1]
  return variable && Object.hasOwn(token, variable) ? token[variable] : value
}

function warning(
  constraint: BrandConstraint,
  fields: Omit<BrandWarning, 'code' | 'constraint'>,
): BrandWarning {
  return {
    code: BRAND_CONSTRAINT_WARNING_POLICY[constraint.action].code,
    constraint: constraint.kind,
    ...fields,
    message: `${fields.message} Recovery: ${BRAND_CONSTRAINT_DESCRIPTORS[constraint.kind].recovery}`,
  }
}

interface TextContrastCandidate {
  readonly node: Extract<SceneNode, { kind: 'text' }>
  readonly background?: string
}

function sameChannels(a: SceneNode, b: SceneNode): boolean {
  const left = a.channels ?? {}
  const right = b.channels ?? {}
  const entries = (value: typeof left) => Object.entries(value)
    .sort(([a], [b]) => compareCodePointStrings(a, b))
  return JSON.stringify(entries(left)) === JSON.stringify(entries(right))
}

type FilledShape = Extract<SceneNode, { kind: 'shape' }>

function descendantText(nodes: readonly SceneNode[]): Array<Extract<SceneNode, { kind: 'text' }>> {
  const texts: Array<Extract<SceneNode, { kind: 'text' }>> = []
  for (const node of nodes) {
    if (node.kind === 'text') texts.push(node)
    else if (node.kind === 'group') texts.push(...descendantText(node.children.map(child => child.node)))
  }
  return texts
}

function containsTextAnchors(shape: FilledShape, child: SceneNode): boolean {
  const bounds = geometryBounds(shape.geometry)
  if (!bounds) return false
  const texts = descendantText([child])
  return texts.length > 0 && texts.every(text =>
    text.x >= bounds.x0 && text.x <= bounds.x1 && text.y >= bounds.y0 && text.y <= bounds.y1)
}

/** Select the visible semantic surface from shapes painted before this child.
 * Equal-rank candidates use the last shape, matching SVG painter order. */
function childSurface(
  preceding: readonly FilledShape[],
  child: SceneNode,
  enclosingGroup: Extract<SceneNode, { kind: 'group' }> | undefined,
): FilledShape | undefined {
  const last = (items: readonly FilledShape[]): FilledShape | undefined => items[items.length - 1]
  return last(preceding.filter(shape => shape.role === child.role && sameChannels(shape, child)))
    ?? (enclosingGroup
      ? last(preceding.filter(shape => shape.role === enclosingGroup.role && sameChannels(shape, enclosingGroup)))
      : undefined)
    ?? last(preceding.filter(shape => containsTextAnchors(shape, child)))
}

function collectTextContrastCandidates(
  nodes: readonly SceneNode[],
  inheritedBackground: string | undefined,
  candidates: TextContrastCandidate[],
  role?: string,
  enclosingGroup?: Extract<SceneNode, { kind: 'group' }>,
): void {
  const preceding: FilledShape[] = []
  for (const node of nodes) {
    if (node.kind === 'shape') {
      if (node.paint.fill !== undefined && node.paint.fill !== 'none' && node.paint.fill !== 'transparent') preceding.push(node)
      continue
    }
    const surface = childSurface(preceding, node, enclosingGroup)
    const background = surface?.paint.fill ?? inheritedBackground
    if (node.kind === 'text') {
      if (!role || node.role === role) candidates.push({ node, background })
      continue
    }
    if (node.kind === 'group') {
      collectTextContrastCandidates(node.children.map(child => child.node), background, candidates, role, node)
    }
  }
}

function contrastConstraint(
  constraint: Extract<BrandConstraint, { kind: 'contrast' }>,
  scene: SceneDoc,
  request: ResolvedRenderRequest,
): BrandWarning {
  const minimum = constraint.minimum ?? 4.5
  if (request.renderOptions.transparent) {
    return warning(constraint, {
      measurement: 'unmeasurable', minimum,
      message: 'Final contrast is unmeasurable for transparent output because the host backdrop is unknown; no ratio was fabricated.',
    })
  }
  const pageBackground = resolvedPaint(request.appearance.colors.bg, request)
  const candidates: TextContrastCandidate[] = []
  collectTextContrastCandidates(scene.parts, pageBackground, candidates, constraint.role)
  if (candidates.length === 0) {
    return warning(constraint, {
      measurement: 'not-applicable', minimum,
      ...(constraint.role ? { role: constraint.role } : {}),
      message: `Contrast constraint has no applicable text mark${constraint.role ? ` for role ${constraint.role}` : ''}.`,
    })
  }

  const measured = candidates.map(candidate => {
    const foreground = resolvedPaint(candidate.node.paint.fill, request)
    const background = resolvedPaint(candidate.background, request)
    const ratio = foreground && background
      ? wcagCssContrastRatio(foreground, background, pageBackground)
      : null
    return { ...candidate, foreground, background, ratio }
  })
  const worst = measured
    .filter(candidate => candidate.ratio !== null)
    .sort((a, b) => a.ratio! - b.ratio!)[0]
  if (worst && worst.ratio! < minimum) {
    const rounded = Math.round(worst.ratio! * 100) / 100
    return warning(constraint, {
      measurement: 'measurable', minimum, ratio: rounded,
      role: worst.node.role, mark: worst.node.id,
      foreground: worst.foreground, background: worst.background,
      message: `Final ${worst.node.role} contrast is ${rounded}:1; expected at least ${minimum}:1. Paint remains unchanged.`,
    })
  }
  const unresolved = measured.find(candidate => candidate.ratio === null)
  if (unresolved) {
    return warning(constraint, {
      measurement: 'unmeasurable', minimum,
      role: unresolved.node.role, mark: unresolved.node.id,
      ...(unresolved.foreground ? { foreground: unresolved.foreground } : {}),
      ...(unresolved.background ? { background: unresolved.background } : {}),
      message: 'Final contrast is unmeasurable because an effective paint pair is unresolved; no ratio was fabricated.',
    })
  }
  const rounded = Math.round(worst!.ratio! * 100) / 100
  return warning(constraint, {
    measurement: 'measurable', minimum, ratio: rounded,
    role: worst!.node.role, mark: worst!.node.id,
    foreground: worst!.foreground, background: worst!.background,
    message: `Final ${worst!.node.role} contrast is ${rounded}:1 and meets ${minimum}:1.`,
  })
}

function sameConcretePaint(left: string, right: string): boolean {
  const a = tryParseCssColor(left)
  const b = tryParseCssColor(right)
  if (!a || !b) return left.trim().toLowerCase() === right.trim().toLowerCase()
  return a.every((channel, index) => Math.abs(channel - b[index]!) < 1e-6)
}

function accentAreaConstraint(
  constraint: Extract<BrandConstraint, { kind: 'accent-area' }>,
  scene: SceneDoc,
  request: ResolvedRenderRequest,
): BrandWarning {
  const accent = resolvedPaint(request.appearance.colors.accent, request)
  if (!accent) return warning(constraint, {
    measurement: 'unmeasurable', maximum: constraint.maxFraction,
    message: 'Accent-area constraint is unmeasurable because no concrete accent paint is resolved.',
  })
  let total = 0
  let accented = 0
  visitSceneNodes(scene.parts, node => {
    if (node.kind !== 'shape' || node.role === 'chrome') return
    const fill = resolvedPaint(node.paint.fill, request)
    if (!fill || fill === 'none' || fill === 'transparent') return
    const bounds = geometryBounds(node.geometry)
    if (!bounds) return
    const area = Math.max(0, bounds.x1 - bounds.x0) * Math.max(0, bounds.y1 - bounds.y0)
    total += area
    if (sameConcretePaint(fill, accent)) accented += area
  })
  if (total === 0) return warning(constraint, {
    measurement: 'not-applicable', maximum: constraint.maxFraction,
    message: 'Accent-area constraint has no applicable filled shape area.',
  })
  const actual = Math.round((accented / total) * 10_000) / 10_000
  return warning(constraint, {
    measurement: 'measurable', actual, maximum: constraint.maxFraction,
    message: actual > constraint.maxFraction
      ? `Accent fill covers ${(actual * 100).toFixed(2)}% of applicable shape area; maximum is ${(constraint.maxFraction * 100).toFixed(2)}%. Paint remains unchanged.`
      : `Accent fill area is within the configured maximum.`,
  })
}

function monoRoleConstraint(
  constraint: Extract<BrandConstraint, { kind: 'mono-role' }>,
  scene: SceneDoc,
  request: ResolvedRenderRequest,
): BrandWarning {
  const paints: Array<{ mark: string; value: string }> = []
  visitSceneNodes(scene.parts, node => {
    if (node.role !== constraint.role) return
    const values = node.kind === 'connector'
      ? [node.stroke.color]
      : node.kind === 'shape' || node.kind === 'text'
        ? [node.paint.fill, node.paint.stroke]
        : []
    for (const value of values) {
      const paint = resolvedPaint(value, request)
      if (paint && paint !== 'none') paints.push({ mark: node.id, value: paint })
    }
  })
  if (paints.length === 0) return warning(constraint, {
    measurement: 'not-applicable', role: constraint.role,
    message: `Mono-role constraint has no applicable paint for role ${constraint.role}.`,
  })
  for (const paint of paints) {
    const parsed = tryParseCssColor(paint.value)
    if (!parsed) return warning(constraint, {
      measurement: 'unmeasurable', role: constraint.role, mark: paint.mark,
      message: `Mono-role paint ${paint.value} is unresolved; no monochrome verdict was fabricated.`,
    })
    if (Math.abs(parsed[0] - parsed[1]) > 1 || Math.abs(parsed[1] - parsed[2]) > 1) {
      return warning(constraint, {
        measurement: 'measurable', role: constraint.role, mark: paint.mark, foreground: paint.value,
        message: `Role ${constraint.role} uses chromatic paint ${paint.value}; the mono-role constraint does not repaint it.`,
      })
    }
  }
  return warning(constraint, {
    measurement: 'measurable', role: constraint.role,
    message: `Role ${constraint.role} uses only measurable monochrome paint.`,
  })
}

const CONSTRAINT_EVALUATORS = {
  contrast: contrastConstraint,
  'accent-area': accentAreaConstraint,
  'mono-role': monoRoleConstraint,
} satisfies { [Kind in BrandConstraint['kind']]: (
  constraint: Extract<BrandConstraint, { kind: Kind }>,
  scene: SceneDoc,
  request: ResolvedRenderRequest,
) => BrandWarning }

function evaluateConstraint(constraint: BrandConstraint, scene: SceneDoc, request: ResolvedRenderRequest): BrandWarning {
  const evaluator = CONSTRAINT_EVALUATORS[constraint.kind] as (
    value: BrandConstraint,
    scene: SceneDoc,
    request: ResolvedRenderRequest,
  ) => BrandWarning
  return evaluator(constraint, scene, request)
}

/** Inspect the exact admitted Scene. Rules report evidence and never mutate it. */
export function evaluateBrandConstraints(scene: SceneDoc, request: ResolvedRenderRequest): LayoutWarning[] {
  const constraints = request.appearance.style?.constraints ?? []
  const results: BrandWarning[] = constraints.map(constraint =>
    evaluateConstraint(constraint, scene, request)).filter(warning => {
    // Passing measurable rules stay silent; explicit unmeasurable/not-applicable
    // states remain observable because the caller asked for the constraint.
    if (warning.measurement !== 'measurable') return true
    if (warning.constraint === 'contrast') return (warning.ratio ?? Infinity) < (warning.minimum ?? 4.5)
    if (warning.constraint === 'accent-area') return (warning.actual ?? 0) > (warning.maximum ?? 1)
    return warning.foreground !== undefined
  })
  return results
}
